#include <furi.h>
#include <gui/gui.h>
#include <input/input.h>
#include <stdlib.h>
#include <stdio.h>
#include <storage/storage.h>
typedef struct {FuriMessageQueue*q; FuriMutex*lock; int hp,enemy,round,live,blank,n,pos,sel,screen,items[3],score,best; bool endless,quit,turn; unsigned seed; char msg[32]; bool shells[8];} Game;
static unsigned rng(Game*g){g->seed=g->seed*1664525u+1013904223u;return g->seed>>16;}
static void load(Game*g){g->n=4+g->round%5;g->pos=0;g->live=g->n/2;g->blank=g->n-g->live;for(int i=0;i<g->n;i++)g->shells[i]=i<g->live;for(int i=g->n-1;i>0;i--){int j=rng(g)%(i+1);bool t=g->shells[i];g->shells[i]=g->shells[j];g->shells[j]=t;}for(int i=0;i<3;i++)g->items[i]=1;snprintf(g->msg,sizeof(g->msg),"%d LIVE / %d BLANK",g->live,g->blank);}
static void record(Game*g,bool read){Storage*s=furi_record_open(RECORD_STORAGE);File*f=storage_file_alloc(s);if(storage_file_open(f,"/ext/buckshot.score",read?FSAM_READ:FSAM_WRITE,read?FSOM_OPEN_EXISTING:FSOM_CREATE_ALWAYS)){if(read)storage_file_read(f,&g->best,sizeof(int));else storage_file_write(f,&g->best,sizeof(int));storage_file_close(f);}storage_file_free(f);furi_record_close(RECORD_STORAGE);}
static void start(Game*g){g->round=1;g->hp=g->enemy=3;g->score=0;g->turn=false;g->screen=1;g->sel=0;load(g);}
static void shot(Game*g,bool self){bool live=g->shells[g->pos++];if(live){g->live--;if(self!=g->turn)g->hp--;else g->enemy--;}else g->blank--;snprintf(g->msg,sizeof(g->msg),live?"LIVE!":"BLANK!");if(g->hp<=0){g->screen=2;return;}if(g->enemy<=0){g->score+=100;g->round++;if(g->score>g->best){g->best=g->score;record(g,false);}if(!g->endless&&g->round>3){g->screen=2;return;}g->hp=g->enemy=3+(g->round%3);g->turn=false;load(g);return;}if(!self||live)g->turn=!g->turn;if(g->pos>=g->n)load(g);}
static void draw(Canvas*c,void*p){Game*g=p;if(furi_mutex_acquire(g->lock,0)!=FuriStatusOk)return;canvas_clear(c);canvas_set_font(c,FontSecondary);char b[40];if(g->screen==0){canvas_set_font(c,FontPrimary);canvas_draw_str(c,4,12,"BUCKSHOT ROULETTE");canvas_set_font(c,FontSecondary);canvas_draw_str(c,5,28,g->sel==0?"> Story":"  Story");canvas_draw_str(c,5,40,g->sel==1?"> Double or Nothing":"  Double or Nothing");snprintf(b,sizeof(b),"Best: %d",g->best);canvas_draw_str(c,5,58,b);}else if(g->screen==2){canvas_draw_str(c,25,20,g->hp<=0?"GAME OVER":"YOU WIN");snprintf(b,sizeof(b),"Score %d",g->score);canvas_draw_str(c,25,36,b);canvas_draw_str(c,25,55,"OK: Menu");}else{canvas_draw_box(c,0,0,128,37);canvas_set_color(c,ColorWhite);canvas_draw_disc(c,64,17,13);canvas_set_color(c,ColorBlack);canvas_draw_box(c,54,12,7,4);canvas_draw_box(c,67,12,7,4);canvas_draw_line(c,55,23,73,23);for(int i=0;i<5;i++)canvas_draw_line(c,56+i*4,21,56+i*4,25);canvas_set_color(c,ColorWhite);snprintf(b,sizeof(b),"YOU %d",g->hp);canvas_draw_str(c,2,8,b);snprintf(b,sizeof(b),"CPU %d",g->enemy);canvas_draw_str(c,91,8,b);canvas_set_color(c,ColorBlack);canvas_draw_line(c,0,38,127,38);canvas_draw_box(c,44,31,40,4);canvas_draw_box(c,77,35,7,4);canvas_draw_str(c,2,46,g->msg);const char* names[]={"Dealer","Self","Peek","Heal","Skip"};canvas_draw_str(c,2,56,g->turn?"Dealer turn":names[g->sel]);canvas_draw_str(c,75,56,"OK / < >");}furi_mutex_release(g->lock);}
static void input(InputEvent*e,void*p){Game*g=p;furi_message_queue_put(g->q,e,0);}
int32_t buckshot_main(void*p){UNUSED(p);Game*g=calloc(1,sizeof(Game));if(!g)return -1;g->seed=furi_get_tick();g->q=furi_message_queue_alloc(8,sizeof(InputEvent));g->lock=furi_mutex_alloc(FuriMutexTypeNormal);record(g,true);ViewPort*v=view_port_alloc();view_port_draw_callback_set(v,draw,g);view_port_input_callback_set(v,input,g);Gui*gui=furi_record_open(RECORD_GUI);gui_add_view_port(gui,v,GuiLayerFullscreen);while(!g->quit){InputEvent e;bool got=furi_message_queue_get(g->q,&e,100)==FuriStatusOk;furi_mutex_acquire(g->lock,FuriWaitForever);if(got&&e.type==InputTypeShort){if(e.key==InputKeyBack){if(g->screen)g->screen=0;else g->quit=true;}else if(g->screen==0){if(e.key==InputKeyUp||e.key==InputKeyDown)g->sel=1-g->sel;if(e.key==InputKeyOk){g->endless=g->sel==1;start(g);}}else if(g->screen==2){if(e.key==InputKeyOk){g->screen=0;g->sel=0;}}else if(!g->turn){if(e.key==InputKeyLeft)g->sel=(g->sel+4)%5;if(e.key==InputKeyRight)g->sel=(g->sel+1)%5;if(e.key==InputKeyOk){if(g->sel<2)shot(g,g->sel==1);else if(g->items[g->sel-2]){g->items[g->sel-2]=0;if(g->sel==2)snprintf(g->msg,sizeof(g->msg),g->shells[g->pos]?"NEXT: LIVE":"NEXT: BLANK");if(g->sel==3)g->hp++;if(g->sel==4){g->pos++;if(g->pos>=g->n)load(g);}}}}}else if(!got&&g->screen==1&&g->turn)shot(g,false);furi_mutex_release(g->lock);view_port_update(v);}gui_remove_view_port(gui,v);view_port_free(v);furi_record_close(RECORD_GUI);furi_mutex_free(g->lock);furi_message_queue_free(g->q);free(g);return 0;}